            }
            // struggling while held or burning
            if ((p.held || p.burning) && !p.dead && rnd.nextFloat() < dt * 6f) {
                RB limb = p.rb[Person.FARM_F + rnd.nextInt(4)];
                limb.applyImpulse((rnd.nextFloat() - 0.5f) * 2.5e5f, (rnd.nextFloat() - 0.5f) * 2.5e5f, limb.x, limb.y);
            }
            p.thinkT -= dt;
            if (p.thinkT <= 0f) {
                p.thinkT = 0.25f + rnd.nextFloat() * 0.15f;
                p.walk = 0; p.run = false; p.aim = false; p.reach = false; p.armsUp = false; p.armsForward = false; p.kneel = false;
                p.walkIdleGuard = false;
                if (p.able && p.tone > 0.6f) { Mind.think(this, p); Mind.avoid(this, p); }
                else { p.target = null; p.mood = p.dead ? "" : (p.ko > 0f ? "Inconsciente" : (p.legsBroken() ? "No puede andar" : "Aturdido")); }
                // keep inside the room
                if (p.walk < 0 && p.rb[Person.PELVIS].x < sim.wallL + 90f) p.walk = 0;
                if (p.walk > 0 && p.rb[Person.PELVIS].x > sim.wallR - 90f) p.walk = 0;
                if (p.walk != 0 && p.walk != p.dir && p.upright() && p.able) p.turn();
                else if (p.walk == 0 && p.target != null && p.able && p.upright()) {
                    float tx = p.target is Person ? ((Person) p.target).rb[Person.CHEST].x : p.target.cx();
                    int want = tx > p.rb[Person.PELVIS].x ? 1 : -1;
                    if (want != p.dir) p.turn();
                }
            }
            Mind.tick(this, p, dt);
        }

        /** Starts the rust infection (the rust bar and the Rust Man's claws do this). Returns true if it took. */
        public bool infectRust(Person p) {
            if (p.dead || p.rustT >= 0f || p.kind == Person.RUSTMAN || p.kind == Person.SKELETON || p.removed) return false;
            p.rustT = 7f;
            fx.add(Fx.SMOKE, p.cx(), p.cy(), fx.rr_(20f), -30f, 1f, 8f, unchecked((int)0x88b5651dU));
            stats.rusted++;
            return true;
        }

        /** The rust takes over: the person becomes a Rust Man. */
        public void rustify(Person p) {
            if (p.dead || p.kind == Person.RUSTMAN) { p.rustT = -1f; return; }
            p.kind = Person.RUSTMAN;
            p.item = Items.RUSTMAN;
            p.rustT = -1f;
            p.skin = unchecked((int)0xFFa8551fU); p.shirt = Renderer.mix(p.shirt, unchecked((int)0xFF4a3220U), 0.7f); p.pants = Renderer.mix(p.pants, unchecked((int)0xFF2f2218U), 0.7f); p.hair = unchecked((int)0xFF3a2410U);
            p.flammable = false;
            p.hpMul = 1.8f;
            p.baseStrength = 1.3f; p.strength = 1.3f; p.speed = 0.85f;
            p.maxBlood = Math.max(p.maxBlood, 230f); p.blood = p.maxBlood;
            p.infected = -1f; p.bitten = false; p.ko = 0f; p.tone = 0f;
            for (int i = 0; i < Person.NPARTS; i++) { p.hp[i] = Person.maxHp(p, i); p.broken[i] = false; p.bleed[i] = 0f; p.soak[i] = 0f; }
            recolor(p);
            RB c = p.rb[Person.CHEST];
            for (int i = 0; i < 18; i++) fx.add(Fx.DEBRIS, c.x + fx.rr_(24f), c.y + fx.rr_(40f), fx.rr_(300f), -fx.rf() * 320f, 1.1f, 2f + fx.rf() * 3f, i % 2 == 0 ? unchecked((int)0xFFb5651dU) : unchecked((int)0xFF7a3a14U));
            for (int i = 0; i < 6; i++) fx.add(Fx.SMOKE, c.x + fx.rr_(20f), c.y + fx.rr_(30f), fx.rr_(60f), -40f - fx.rf() * 60f, 1.4f, 8f, unchecked((int)0x99a05a20U));
            fx.sparks(c.x, c.y, 16, unchecked((int)0xFFff9a3aU));
            fx.flash = Math.min(1f, fx.flash + 0.25f);
            if (sfx != null) { sfx.crunch(); sfx.zap(); }
            alarm(c.x, c.y, 900f, 8f);
            rumble += 0.4f;
        }

        /** Blood V6: what soaks a body drips off its lowest parts, drop by drop, and falls into the pools below. */
        private void dripOff(Person p, float dt) {
            for (int i = 0; i < Person.NPARTS; i++) {
                float k = p.soak[i];
                if (k < 0.3f || p.gibbed[i] || rnd.nextFloat() > dt * k * 2.4f) continue;
                RB b = p.rb[i];
                if (b.y > sim.floorY - 6f) continue;
                Shape sh = b.shapes.get(0);
                bloodStyle(p);
                float lowY = sh.type == Shape.CAPSULE ? Math.max(sh.cy + Math.abs(sh.ay) * sh.hl, sh.cy) + sh.r * 0.7f : sh.cy + sh.r * 0.7f;
                fx.add(Fx.BLOOD, sh.cx + fx.rr_(sh.r * 0.5f), lowY, fx.rr_(12f) + b.vx * 0.2f, 10f, 1.6f, 2f + fx.rf() * 1.6f, rnd.nextBoolean() ? fx.bloodB : fx.bloodA);
                p.soak[i] = Math.max(0f, p.soak[i] - 0.012f);
            }
        }

        /** Gore V6: the heart still pushes blood out of an open stump, in jets with each beat, and a ruined chest makes them cough blood. */
        private void bloodPressure(Person p, float dt) {
            float beat = (float) Math.sin(time * 9f + p.id);
            if (beat > 0.6f) {
                for (int j = 0; j < Person.NJOINTS; j++) {
                    if (!p.severed[j] || j == Person.NECK || j == Person.WAIST) continue;
                    int part = stumpParts(j)[0];
                    if (p.gibbed[part] || p.bleed[part] <= 0f || rnd.nextFloat() > dt * 26f) continue;
                    Joint jn = p.jt[j];
                    RB body = p.rb[part];
                    float ax = jn.a == body ? jn.anchorAX() : jn.anchorBX(), ay = jn.a == body ? jn.anchorAY() : jn.anchorBY();
                    float ox = ax - body.x, oy = ay - body.y, ol = (float) Math.sqrt(ox * ox + oy * oy) + 1e-3f;
                    float jet = Math.min(1f, p.bleed[part] / 9f);
                    bloodStyle(p);
                    fx.arterial(ax, ay, ox / ol, oy / ol - 0.1f, 2 + (int) (jet * 4f));
                }
            }
            if (p.hp[Person.CHEST] < -15f && !p.gibbed[Person.HEAD] && rnd.nextFloat() < dt * 1.6f) {
                RB h = p.rb[Person.HEAD];
                bloodStyle(p);
                fx.blood(h.x + p.dir * 10f * p.scale, h.y + 8f * p.scale, p.dir * 0.8f, 0.1f, 2);
                p.soak[Person.HEAD] = Math.min(1f, p.soak[Person.HEAD] + 0.04f);
            }
        }

        /** Gore V5 on the floor: bleeding bodies lying down make a growing pool, and feet that step in blood leave prints. */
        private void goreFloor(Person p, float dt) {
            bloodStyle(p);
            int col = Renderer.alpha(fx.bloodA, 0.85f);
            // a pool under every bleeding part that rests on the floor
            for (int i = 0; i < Person.NPARTS; i++) {
                if (p.bleed[i] <= 0f || p.gibbed[i]) continue;
                RB b = p.rb[i];
                if (b.y < sim.floorY - 34f) continue;
                if (rnd.nextFloat() < dt * 5f) fx.stain(b.x + fx.rr_(8f), 3f + Math.min(5f, p.bleed[i] * 0.4f), col);
            }
            // feet in a pool get soaked, then print
            p.printT -= dt;
            int[] feet = {Person.FOOT_F, Person.FOOT_B};
            foreach (int f in feet) {
                if (p.gibbed[f]) continue;
                RB b = p.rb[f];
                if (b.y < sim.floorY - 26f) continue;
                if (fx.poolAt(b.x) > 12f) p.soak[f] = Math.min(1f, p.soak[f] + dt * 0.9f);
                if (p.soak[f] > 0.25f && p.printT <= 0f && Math.abs(b.vx) > 25f && !p.dead) {
                    fx.stain(b.x, 4.5f, unchecked((int)0xB08a0a12U));
                    p.soak[f] = Math.max(0f, p.soak[f] - 0.05f);
                    p.printT = 0.2f;
                }
            }
        }

        public void kill(Person p) {
            if (p.dead) return;
            p.dead = true;
            p.blood = 0f;
            p.tone = 0f;
            p.deadT = 0f;
            p.convT = p.fleshy() ? 1.6f : 0f;       // gore V6: the body convulses for a moment after death
            stats.kills++;
        }

        /** A bitten person rises again as a zombie. */
        public void reanimate(Person p) {
            if (!p.intact() || p.removed) return;
            p.kind = Person.ZOMBIE;
            p.item = Items.ZOMBIE;
            p.target = null;
            stats.infections++;
            p.skin = unchecked((int)0xFF7fa65aU);
            p.shirt = Renderer.mix(p.shirt, unchecked((int)0xFF4a473aU), 0.6f);
            p.dead = false; p.blood = 120f; p.ko = 1.5f; p.tone = 0f; p.baseStrength = 0.8f; p.speed = 0.55f;
            for (int i = 0; i < Person.NPARTS; i++) { p.broken[i] = false; if (p.hp[i] < 40f) p.hp[i] = 40f; }
            recolor(p);
            fx.smoke(p.rb[Person.HEAD].x, p.rb[Person.HEAD].y, 12, unchecked((int)0xFF5aa02aU));
            if (sfx != null) sfx.splat();
        }

        public void recolor(Person p) {
            int[] cols = {p.pants, p.shirt, p.skin, p.shirt, p.skin, p.shirt, p.skin, p.pants, p.pants, unchecked((int)0xFF2b2b30U), p.pants, p.pants, unchecked((int)0xFF2b2b30U)};
            for (int i = 0; i < Person.NPARTS; i++) if (!p.rb[i].shapes.isEmpty()) p.rb[i].shapes.get(0).color = cols[i];
        }

        // damage ------------------------------------------------------------------------------------

        public void bloodStyle(Person p) {
            switch (p.kind) {
                case Person.ZOMBIE: fx.bloodA = unchecked((int)0xFF5aa02aU); fx.bloodB = unchecked((int)0xFF3b6e1aU); break;
                case Person.RUSTMAN: fx.bloodA = unchecked((int)0xFFb5481aU); fx.bloodB = unchecked((int)0xFF6e2a0cU); break;
                case Person.ROBOT: fx.bloodA = unchecked((int)0xFF2b2b2fU); fx.bloodB = unchecked((int)0xFF4a4a52U); break;
                case Person.SKELETON: fx.bloodA = unchecked((int)0xFFe9e5d3U); fx.bloodB = unchecked((int)0xFFc9c4adU); break;
                default: fx.bloodA = unchecked((int)0xFFa80f18U); fx.bloodB = unchecked((int)0xFF5e0a0fU); break;
            }
        }

        /** Damage to one part of a person. Heavy hits knock people out, break bones, open wounds. */
        public void hurt(Person p, int part, float dmg, float x, float y, float dx, float dy) {
            if (dmg <= 0f || part < 0) return;
            bloodStyle(p);
            p.flash = 0.12f;
            p.hp[part] -= dmg;
            if (p.kind == Person.ROBOT) fx.sparks(x, y, 4, unchecked((int)0xFFffd25aU));
            else if (p.kind == Person.SKELETON) fx.debris(x, y, 2, unchecked((int)0xFFf0ead6U), 160f);
            else if (dmg > 3f) {
                fx.blood(x, y, dx, dy, (int) Math.min(10, 2 + dmg * 0.25f));
                if (dmg > 12f && fx.gore && p.fleshy()) for (int mk = 0; mk < 8; mk++) fx.add(Fx.BLOOD, x, y, dx * 120f + fx.rr_(220f), dy * 120f - fx.rf() * 200f, 0.6f, 1.1f, fx.bloodA);   // a fine mist
                if (p.fleshy()) {
                    p.soak[part] = Math.min(1f, p.soak[part] + dmg * 0.012f);
                    // a hard hit sprays the wall behind
                    if (dmg > 14f && fx.gore && rnd.nextFloat() < 0.5f) { fx.wallSplat(x + dx * 30f + fx.rr_(20f), y + dy * 20f + fx.rr_(20f), 6f + Math.min(18f, dmg * 0.25f), fx.bloodA); stats.splats++; }
                }
            }
            if (!p.dead && p.organic()) p.blood -= dmg * 0.22f;
            if (!p.dead && p.kind == Person.ZOMBIE) p.blood -= dmg * 0.18f;
            if (dmg > 9f && !p.dead) {
                float kt = Math.min(5f, 1.1f + dmg * 0.06f) * (p.kind == Person.ROBOT ? 0.5f : 1f);
                p.ko = Math.max(p.ko, kt);
                p.tone = 0f;
            }
            if (p.hp[part] <= 0f && !p.broken[part]) {
                p.broken[part] = true;
                if (sfx != null) sfx.crunch();
                if (p.organic()) p.bleed[part] = Math.max(p.bleed[part], 6f);
                if (part == Person.HEAD) { if (!p.dead) { kill(p); } }
                else if (part == Person.CHEST && !p.dead && p.hp[Person.CHEST] < -40f) kill(p);
                else if (!p.dead) { p.ko = Math.max(p.ko, 0.6f); p.tone = 0f; }
            }
            if (p.blood <= 0f && !p.dead) kill(p);
            // a part far beyond destroyed bursts into pieces
            if (p.hp[part] < -Person.maxHp(p, part) * 1.7f && dmg > 20f && !p.gibbed[part]) { gib(p, part, dx, dy); return; }
            // deep damage tears the joint (dismemberment) for the extremities
            if (p.hp[part] < -60f) {
                int j = Person.PART_JOINT[part];
                if (j >= 0 && j != Person.WAIST && !p.severed[j]) sever(p, j, x, y);
            }
            rumble += Math.min(0.5f, dmg * 0.01f);
        }

        public static readonly int[][] DETACH = {
            new int[] {Person.HEAD},
            new int[] {Person.CHEST, Person.HEAD, Person.UARM_F, Person.FARM_F, Person.UARM_B, Person.FARM_B},
            new int[] {Person.UARM_F, Person.FARM_F}, new int[] {Person.FARM_F}, new int[] {Person.UARM_B, Person.FARM_B}, new int[] {Person.FARM_B},
            new int[] {Person.THIGH_F, Person.SHIN_F, Person.FOOT_F}, new int[] {Person.SHIN_F, Person.FOOT_F}, new int[] {Person.FOOT_F},
            new int[] {Person.THIGH_B, Person.SHIN_B, Person.FOOT_B}, new int[] {Person.SHIN_B, Person.FOOT_B}, new int[] {Person.FOOT_B},
        };

        /** Cuts a joint: the limb flies off. */
        public void sever(Person p, int j, float x, float y) {
            if (p.severed[j]) return;
            Joint jn = p.jt[j];
            if (!jn.removed) sim.remove(jn);
            p.severed[j] = true;
            stats.severed++;
            jn.muscle = false;
            int g = ++Person.groupSeq;
            foreach (int part in DETACH[j]) foreach (Shape s in p.rb[part].shapes) s.group = g;
            bloodStyle(p);
            if (p.fleshy()) {
                fx.blood(x, y, 0f, -0.3f, 18);
                fx.wallSplat(x + fx.rr_(25f), y + fx.rr_(20f), 9f + fx.rf() * 10f, fx.bloodA);
                foreach (int part in stumpParts(j)) { p.bleed[part] = Math.max(p.bleed[part], 9f); p.soak[part] = Math.min(1f, p.soak[part] + 0.3f); }
                foreach (int part in DETACH[j]) { p.bleed[part] = Math.max(p.bleed[part], 6f); p.soak[part] = Math.min(1f, p.soak[part] + 0.5f); }
                if (!p.dead) p.blood -= 6f;
            } else fx.sparks(x, y, 14, unchecked((int)0xFFffd25aU));
            if (sfx != null) sfx.crunch();
            alarm(x, y, 450f, 3f);
            if (!p.dead) { p.ko = Math.max(p.ko, j == Person.NECK ? 99f : 1.2f); p.tone = 0f; }
            if (j == Person.NECK || j == Person.WAIST) kill(p);
            rumble += 0.3f;
        }

        private static int[] stumpParts(int j) {
            switch (j) {
                case Person.NECK: return new int[]{Person.CHEST};
                case Person.SH_F: case Person.EL_F: return new int[]{j == Person.SH_F ? Person.CHEST : Person.UARM_F};
                case Person.SH_B: case Person.EL_B: return new int[]{j == Person.SH_B ? Person.CHEST : Person.UARM_B};
                case Person.HIP_F: case Person.HIP_B: return new int[]{Person.PELVIS};
                case Person.KNEE_F: return new int[]{Person.THIGH_F};
                case Person.KNEE_B: return new int[]{Person.THIGH_B};
                default: return new int[]{Person.PELVIS};
             break; }
        }

        public void jointBroken(Joint j) {
            if (j.tag == Build.TAG) {                       // a construction let go: pieces fall and debris flies
                float x = j.anchorBX(), y = j.anchorBY();
                fx.debris(x, y, 7, Build.WOOD, 200f);
                fx.dust(x, y, 26f, 3);
                fx.smoke(x, y, 10, unchecked((int)0xFF9a9a9aU));
                for (int k = 0; k < 3; k++) fx.smoke(x + fx.rr_(30f), y + fx.rr_(20f), 12f, unchecked((int)0xFFb3a595U));
                // the structure around a lost joint carries more load: its pieces weaken and crack, so collapses spread
                for (int side = 0; side < 2; side++) {
                    RB rb = side == 0 ? j.a : j.b;
                    if (rb == null || !(rb.user is Prop)) continue;
                    Prop o = (Prop) rb.user;
                    if (!breakable(o) || o.removed) continue;
                    crack(o, x, y, 0.3f);
                    wear(o, toughness(o) * 0.22f, true);
                }
                stats.collapses++;
                if (sfx != null) sfx.crunch();
                stats.destroyed++;
                rumble += 0.12f;
                return;
            }
            if (j.tag == Machines.IMPALE_TAG) {             // pulled off the spikes
                fx.bloodA = unchecked((int)0xFFa80f18U); fx.bloodB = unchecked((int)0xFF5e0a0fU);
                fx.blood(j.anchorBX(), j.anchorBY(), 0f, -0.5f, 8);
                if (sfx != null) sfx.splat();
                return;
            }
            if (j.user is Person) {
                Person p = (Person) j.user;
                int idx = j.tag;
                if (idx >= 0 && idx < Person.NJOINTS && !p.severed[idx]) {
                    j.removed = true;
                    // already removed by the Sim: replay the bookkeeping
                    p.severed[idx] = true;
                    stats.severed++;
                    int g = ++Person.groupSeq;
                    foreach (int part in DETACH[idx]) foreach (Shape s in p.rb[part].shapes) s.group = g;
                    bloodStyle(p);
                    float x = j.anchorBX(), y = j.anchorBY();
                    if (p.fleshy()) {
                        fx.blood(x, y, 0f, -0.3f, 18);
                        foreach (int part in stumpParts(idx)) p.bleed[part] = Math.max(p.bleed[part], 9f);
                        foreach (int part in DETACH[idx]) p.bleed[part] = Math.max(p.bleed[part], 6f);
                        if (!p.dead) p.blood -= 6f;
                    } else fx.sparks(x, y, 14, unchecked((int)0xFFffd25aU));
                    if (sfx != null) sfx.crunch();
                    if (!p.dead) { p.ko = Math.max(p.ko, idx == Person.NECK ? 99f : 1.2f); p.tone = 0f; }
                    if (idx == Person.NECK || idx == Person.WAIST) kill(p);
                    rumble += 0.3f;
                }
            } else if (j.user is Prop && ((Prop) j.user).type == Items.ROPE_ITEM) {
                fx.sparks(j.anchorBX(), j.anchorBY(), 6, unchecked((int)0xFFe8c48aU));
            }
        }

        // impacts ------------------------------------------------------------------------------------

        /** per-part damage cooldown shared by both sides of a contact */
        public void impact(Shape a, Shape b, float dv, float px, float py, float nx, float ny) {
            impactOn(a, b, dv, px, py, -nx, -ny);
            if (b != null) impactOn(b, a, dv, px, py, nx, ny);
            else if (dv > 300f) { if (sfx != null) sfx.thud(Math.min(1f, dv / 1400f)); rumble += Math.min(0.3f, dv * 0.0002f); }
            if (dv > 600f && b != null && sfx != null) sfx.thud(Math.min(1f, dv / 1600f));
        }

        private void impactOn(Shape s, Shape other, float dv, float px, float py, float dx, float dy) {
            Object u = s.body.user;
            if (u is Person) {
                Person p = (Person) u;
                if (p.removed) return;
                int part = Person.partOf(p, s);
                if (part < 0 || p.hitCd[part] > 0f) return;
                float thr = part == Person.HEAD ? 520f : (part == Person.FOOT_F || part == Person.FOOT_B ? 1250f : (part == Person.SHIN_F || part == Person.SHIN_B ? 1000f : (part >= Person.THIGH_F ? 880f : 640f)));
                if (p.kind == Person.ROBOT) thr *= 1.6f;
                bool sharp = other != null && other.body.user is Prop && ((Prop) other.body.user).sharp;
                if (p.frozenT > 0f && dv > 1150f) { shatterQ.add(p); return; }
                if (sharp && dv > 220f && ((Prop) other.body.user).type == Items.SPIKES) { impQ.add(p); impQP.add(part); impQS.add((Prop) other.body.user); impQX.add(px); impQY.add(py); p.hitCd[part] = 0.3f; return; }
                float heavy = 1f;
                if (other != null) {
                    float om = other.body.invM > 0f ? other.body.m : 20000f;
                    heavy = Math.max(0.35f, Math.min(2.2f, (float) Math.sqrt(om / Math.max(1f, s.body.m)) * 0.9f));
                    if (other.body.user is Person) heavy = Math.min(heavy, 0.9f);
                }
                if (sharp && dv > 140f) {
                    p.hitCd[part] = 0.18f;
                    Prop blade = (Prop) other.body.user;
                    if ((Items.isTrap(blade.type) || blade.type == Items.KNIFE || blade.type == Items.SWORD || blade.type == Items.SAW) && flesh(p)) blade.wear = Math.min(1f, blade.wear + 0.15f);
                    bool glassEdge = ((Prop) other.body.user).color == Build.GLASS;
                    wound(p, part, Person.W_CUT, px, py, dx, dy, (5f + Math.min(9f, dv * 0.01f)) * (glassEdge ? 0.6f : 1f));
                    hurt(p, part, (8f + dv * 0.05f) * (glassEdge ? 0.3f : 1f), px, py, dx, dy);
                    if (dv > 330f && rnd.nextFloat() < (glassEdge ? 0.06f : 0.55f)) {
                        int j = Person.PART_JOINT[part];
                        if (j >= 0 && j != Person.WAIST && !p.severed[j]) sever(p, j, px, py);
                    }
                    stats.hits++;
                } else if (dv > thr) {
                    p.hitCd[part] = 0.2f;
                    if (dv > thr * 4.5f && heavy >= 0.9f && p.kind != Person.ROBOT) { gibQ.add(p); gibQP.add(part); return; }
                    float d = (dv - thr) * 0.05f * heavy;
                    if (d > 6f) wound(p, part, Person.W_BRUISE, px, py, dx, dy, 3f + Math.min(7f, d * 0.25f));
                    hurt(p, part, d, px, py, dx, dy);
                }
                // a hurt person drops what they were doing when thrown hard
                if (dv > 1000f && !p.dead && p.ko <= 0f && (part == Person.PELVIS || part == Person.CHEST || part == Person.HEAD)) { p.ko = 0.9f; p.tone = 0f; }
            } else if (u is Prop) {
                Prop q = (Prop) u;
                if (q.removed) return;
                bool sharp = other != null && (other.body.user is Prop && ((Prop) other.body.user).sharp);
                if (q.type == Items.BALLOON) { if (dv > 90f || sharp) pop(q); return; }
                if (q.type == Items.MELON) { if (dv > 480f || (sharp && dv > 100f)) smash(q); return; }
                if (q.type == Items.POOP) { if (dv > 700f && q.age > 0.5f) squish(q); return; }
                if (q.gib && q.bloody && fx.gore && dv > 240f && q.splatT <= 0f) {
                    q.splatT = 0.25f;
                    for (int k = 0; k < 4; k++) fx.add(Fx.BLOOD, px, py, dx * 90f + fx.rr_(140f), -fx.rf() * 220f, 1.5f, 2f + fx.rf() * 3f, q.color2);
                    if (sfx != null && dv > 420f) sfx.splat();
                }
                if (q.animal()) {
                    if (sharp && dv > 150f) hurtAnimal(q, 10f + dv * 0.04f, px, py, dx, dy);
                    if (!sharp && dv > 750f) hurtAnimal(q, (dv - 750f) * 0.05f, px, py, dx, dy);
                    return;
                }
                if (q.explosive && q.fuse < 0f && q.type != Items.C4 && dv > 1500f && q.age > 0.8f) q.fuse = 0.05f;
                if (q.machine() && dv > 600f) damageMachine(q, (dv - 600f) * 0.08f);
                if (breakable(q)) {
                    float th = q.color == Build.GLASS ? 150f : (sharp ? 200f : 650f);
                    // the contact speed is noisy for heavy welded stacks: cap it by how fast things were really moving
                    float osp = other == null ? 0f : (other.body.user is Prop ? ((Prop) other.body.user).lastSp : (float) Math.hypot(other.body.vx, other.body.vy));
                    dv = Math.min(dv, q.lastSp + osp);
                    if (dv > th) {
                        float heavy = 1f;
                        if (other != null) {
                            float om = other.body.invM > 0f ? other.body.m : 20000f;
                            heavy = Math.max(0.3f, Math.min(2.5f, (float) Math.sqrt(om / Math.max(1f, s.body.m))));
                        }
                        float dmg = (dv - th) * 0.04f * heavy * (sharp ? 2f : 1f);
                        crack(q, px, py, dmg / Math.max(20f, toughness(q)));
                        wear(q, dmg, true);
                    }
                } else if ((q.type == Items.BARREL || q.type == Items.XBARREL || q.type == Items.STEEL || q.type == Items.FRIDGE) && dv > 520f) {
                    crack(q, px, py, (dv - 520f) * 0.0012f);       // dents and scratches
                }
            }
        }

        // --------------------------------------------------------------------------- destruction ---

        /** Records a wound on the skin of a part (bullet hole, cut, burn, bruise) in its own frame. */
        public void wound(Person p, int part, int kind, float x, float y, float dx, float dy, float size) {
            if (part < 0 || p.gibbed[part] || p.rb[part].shapes.isEmpty()) return;
            Shape s = p.rb[part].shapes.get(0);
            float ex = x - s.cx, ey = y - s.cy;
            float u = ex * s.ax + ey * s.ay, v = -ex * s.ay + ey * s.ax;
            if (s.type == Shape.CAPSULE) {
                u = Math.max(-s.hl - s.r * 0.4f, Math.min(s.hl + s.r * 0.4f, u));
                v = Math.max(-s.r * 0.62f, Math.min(s.r * 0.62f, v));
            } else if (s.type == Shape.CIRCLE) {
                float d = (float) Math.sqrt(u * u + v * v), m = s.r * 0.62f;
                if (d > m) { u *= m / d; v *= m / d; }
            } else {
                u = Math.max(-s.hl * 0.85f, Math.min(s.hl * 0.85f, u));
                v = Math.max(-s.hh * 0.85f, Math.min(s.hh * 0.85f, v));
            }
            int i = p.wNext;
            p.wNext = (p.wNext + 1) % Person.MAXW;
            if (p.nw < Person.MAXW) p.nw++;
            p.wpart[i] = (byte) part; p.wkind[i] = (byte) kind; p.wt[i] = 0f;
            p.wu[i] = u; p.wv[i] = v; p.ws[i] = size * p.scale;
            // cuts follow the blow direction, in the shape frame
            p.wa[i] = (float) Math.atan2(-dx * s.ay + dy * s.ax, dx * s.ax + dy * s.ay) + (rnd.nextFloat() - 0.5f) * 0.6f;
        }

        /** Blows a part of a person into meat (or metal, or bone) chunks. */
        public void gib(Person p, int part, float dx, float dy) { gib(p, part, dx, dy, true); }

        /** chunks=false: the part just disappears (eaten) with a little blood. */
        public void gib(Person p, int part, float dx, float dy, bool chunks) {
            if (p.removed || part < 0 || p.gibbed[part]) return;
            RB b = p.rb[part];
            float bx = b.x, by = b.y, vx = b.vx, vy = b.vy;
            for (int j = 0; j < Person.NJOINTS; j++) {
                Joint jn = p.jt[j];
                if (!p.severed[j] && (jn.a == b || jn.b == b)) sever(p, j, bx, by);
            }
            p.gibbed[part] = true;
            p.bleed[part] = 0f;
            foreach (Shape s in b.shapes) s.sensor = true;
            b.vx = b.vy = 0f; b.w = 0f;
            b.setFrozen(true);
            for (int k = 0; k < p.nw; k++) if (p.wpart[k] == part) p.ws[k] = 0f;
            stats.gibs++;
            bloodStyle(p);
            if (fx.gore && p.fleshy()) {
                // gore V5: whoever stands near gets sprayed
                for (int k = 0; k < ents.size(); k++) {
                    Ent e2 = ents.get(k);
                    if (!(e2 is Person) || e2 == p) continue;
                    Person q2 = (Person) e2;
                    float dd = (float) Math.abs(q2.cx() - bx);
                    if (dd > 260f || !q2.fleshy()) continue;
                    float amt = 0.45f * (1f - dd / 260f);
                    for (int pi = 0; pi < Person.NPARTS; pi++) q2.soak[pi] = Math.min(1f, q2.soak[pi] + amt * (pi == Person.CHEST || pi == Person.HEAD || pi == Person.UARM_F ? 1f : 0.5f));
                }
            }
            bool metal = p.kind == Person.ROBOT, bone = p.kind == Person.SKELETON;
            Shape s0 = b.shapes.get(0);
            float size = s0.type == Shape.CIRCLE ? s0.r : (s0.type == Shape.CAPSULE ? s0.r + s0.hl * 0.35f : (s0.hl + s0.hh) * 0.4f);
            if (chunks) spawnGibs(p, part, bx, by, vx, vy, dx, dy, size, s0.color, metal, bone);
            if (p.frozenT > 0f) { fx.debris(bx, by, 6, unchecked((int)0xFFcfeeffU), 260f); }
            else if (!chunks) { fx.blood(bx, by, 0f, -0.4f, 8); if (sfx != null) sfx.splat(); }
            else if (metal) { fx.sparks(bx, by, 24, unchecked((int)0xFFffd25aU)); fx.smoke(bx, by, 10f, unchecked((int)0xFF3c3c3cU)); }
            else if (bone) fx.debris(bx, by, 12, unchecked((int)0xFFf0ead6U), 320f);
            else {
                // a mist of blood in every direction, a heavier spray along the blow, and a few droplets that hang
                if (fx.gore && p.fleshy()) {
                    for (int k = 0; k < 3; k++) fx.wallSplat(bx + dx * 30f + fx.rr_(60f), by + dy * 20f + fx.rr_(45f), 14f + fx.rf() * 20f, k == 0 ? fx.bloodA : fx.bloodB);
                    stats.splats += 3;
                }
                for (int k = 0; k < 8; k++) { float an = k * 0.785f + rnd.nextFloat() * 0.4f; fx.blood(bx, by, (float) Math.cos(an), (float) Math.sin(an) - 0.3f, 6); }
                fx.blood(bx, by, dx, dy, 22);
                fx.debris(bx, by, 6, p.kind == Person.ZOMBIE ? unchecked((int)0xFF4f7d2aU) : unchecked((int)0xFF8e1111U), 300f);
                for (int k = 0; k < 5; k++) fx.add(Fx.SMOKE, bx + fx.rr_(14f), by + fx.rr_(14f), fx.rr_(60f), -30f - fx.rf() * 50f, 0.9f, 6f + fx.rf() * 6f, p.kind == Person.ZOMBIE ? unchecked((int)0x886aa63aU) : unchecked((int)0x88a3202aU));
            }
            if (sfx != null && chunks) { sfx.splat(); sfx.crunch(); }
            if (chunks) alarm(bx, by, 700f, 5f);
            if (!p.dead && (part == Person.HEAD || part == Person.CHEST || part == Person.PELVIS)) kill(p);
            else if (!p.dead) { p.ko = Math.max(p.ko, 2f); p.tone = 0f; p.blood -= 15f; if (p.blood <= 0f) kill(p); }
            if (chunks) rumble += 0.35f;
        }

        // -------------------------------------------------------------------------------- fridge ---

        /** The fridge door swings; once it is wide open the frozen person inside topples out. */
        private void fridgeTick(Prop q, float dt) {
            float target = q.on ? 1f : 0f;
            if (q.work < target) q.work = Math.min(target, q.work + dt * 2.2f);
            else if (q.work > target) q.work = Math.max(target, q.work - dt * 2.2f);
            if (q.main().invM > 0f) q.main().setFrozen(true);           // fridges stay where they are
            bool cold = q.work > 0.15f && q.meal != null;
            if (cold && rnd.nextFloat() < dt * 14f)
                fx.add(Fx.SMOKE, q.cx() + fx.rr_(q.hw * 0.8f), q.cy() + q.hh * 0.6f, q.homeDirV * (20f + fx.rf() * 30f), 10f + fx.rf() * 20f, 1.6f, 5f + fx.rf() * 4f, unchecked((int)0x99cfeeffU));
            if (q.on && q.work >= 0.99f && q.meal != null && !q.meal.removed) releaseInmate(q.meal, q.homeDirV);
        }

        public void toggleFridge(Prop q) {
            q.on = !q.on;
            if (sfx != null) sfx.thud(0.35f);
        }

        /** Wakes the frozen person up from the fridge (or wherever it was held): the statue tips over, ice and all. */
        public void releaseInmate(Person in_, int out_) {
            Prop fr = in_.cell;
            in_.cell = null;
            if (fr != null) fr.meal = null;
            for (int k = 0; k < Person.NPARTS; k++) {
                if (in_.gibbed[k]) continue;
                RB b = in_.rb[k];
                b.setFrozen(false);
                foreach (Shape sh in b.shapes) sh.sensor = false;
            }
            in_.frozenT = 40f;
            in_.ko = 40f;
            in_.tone = 0f;
            for (int k = 0; k < Person.NPARTS; k++) {
                if (in_.gibbed[k]) continue;
                RB b = in_.rb[k];
                float lift = k == Person.HEAD || k == Person.CHEST ? 1f : 0.45f;
                b.vx = out_ * 210f * lift; b.vy = -30f;
            }
            RB h = in_.rb[Person.HEAD];
            h.applyImpulse(out_ * h.m * 90f, 0f, h.x, h.y);
            stats.fridges++;
            RB c = in_.rb[Person.CHEST];
            for (int i = 0; i < 16; i++) fx.add(Fx.SMOKE, c.x + fx.rr_(40f), c.y + fx.rr_(60f), out_ * (40f + fx.rf() * 80f), fx.rr_(30f), 1.6f, 6f + fx.rf() * 5f, unchecked((int)0xAAdff4ffU));
            if (sfx != null) sfx.crunch();
            rumble += 0.15f;
        }

        /** Puts a frozen person inside a new fridge. */
        private void stockFridge(Prop fr, float x) {
            Person in_ = newPerson(x, sim.floorY - 93f, 1f, fr.homeDirV, Person.HUMAN);
            if (in_ == null) return;
            Machines.freeze(this, in_, 1e9f);
            in_.cell = fr; fr.meal = in_;
            foreach (RB b in in_.rb) {
                b.vx = b.vy = b.w = 0f;
                b.setFrozen(true);
                foreach (Shape sh in b.shapes) sh.sensor = true;
            }
            foreach (RB b in fr.bodies) foreach (Shape sh in b.shapes) sh.group = in_.group;
        }

        /** People nearby panic: they run away from this spot for a while. */
        public void alarm(float x, float y, float r, float secs) {
            for (int i = 0; i < ents.size(); i++) {
                Ent e = ents.get(i);
                if (!(e is Person)) continue;
                Person q = (Person) e;
                if (q.kind != Person.HUMAN || q.dead || Math.abs(q.cx() - x) > r || Math.abs(q.cy() - y) > r) continue;
                q.panicT = Math.max(q.panicT, secs);
                q.alarmX = x;
            }
        }

        /** One loose chunk (flesh, bone, organ or metal) thrown out of a gibbed part. */
        private Prop chunk(float x, float y, float hw, float hh, int col, int col2, bool round, bool isBone, bool bloody, float dens,
                           float vx, float vy, float dx, float dy, float power) {
            if (!canAdd()) return null;
            Prop c = round ? Prop.gibBall(x, y, hw, col, dens) : Prop.block(x, y, hw, hh, col, dens, false);
            c.gib = true; c.round = round; c.bone = isBone; c.bloody = bloody; c.color2 = col2;
            c.register(sim);
            RB r = c.main();
            r.setAngle(rnd.nextFloat() * 6.283f);
            float sp = (180f + rnd.nextFloat() * 420f) * power, ang = rnd.nextFloat() * 6.283f;
            r.vx = vx * 0.5f + dx * 220f + (float) Math.cos(ang) * sp;
            r.vy = vy * 0.5f + dy * 220f + (float) Math.sin(ang) * sp - 160f;
            r.w = fx.rr_(34f);
            add(c);
            keepChunk(c);
            return c;
        }

        /** What a part is made of when it bursts: meat with a raw inside, bone shards, organs; or plates and gears for robots. */
        private void spawnGibs(Person p, int part, float bx, float by, float vx, float vy, float dx, float dy, float size, int outer, bool metal, bool skeleton) {
            bool gore = fx.gore, zombie = p.kind == Person.ZOMBIE, ice = p.frozenT > 0f;
            int raw = zombie ? unchecked((int)0xFF8a9b3aU) : unchecked((int)0xFFb0252fU);
            int bonec = unchecked((int)0xFFe9e5d3U);
            bool limb = part != Person.CHEST && part != Person.PELVIS && part != Person.HEAD;
            if (metal) {
                for (int k = 0; k < 4; k++) chunk(bx + fx.rr_(size), by + fx.rr_(size), Math.max(3.5f, size * (0.3f + rnd.nextFloat() * 0.3f)), Math.max(2.5f, size * 0.2f),
                        k % 2 == 0 ? unchecked((int)0xFF6b737dU) : dark(outer, 0.2f), 0, false, false, false, 2f, vx, vy, dx, dy, 1f);
                for (int k = 0; k < 2; k++) chunk(bx + fx.rr_(size), by + fx.rr_(size), 4.5f, 4.5f, unchecked((int)0xFF8d96a3U), 0, true, false, false, 2.4f, vx, vy, dx, dy, 1f);
                return;
            }
            int nFlesh = skeleton ? 0 : (part == Person.CHEST ? 4 : (part == Person.PELVIS ? 3 : (part == Person.HEAD ? 2 : 3)));
            for (int k = 0; k < nFlesh; k++) {
                float hw = Math.max(3.5f, size * (0.3f + rnd.nextFloat() * 0.3f)), hh = Math.max(3f, hw * (0.55f + rnd.nextFloat() * 0.4f));
                int col = ice ? Renderer.mix(k % 2 == 0 ? outer : raw, unchecked((int)0xFFcfeeffU), 0.6f) : outer;
                int inner = ice ? unchecked((int)0xFFe6f6ffU) : (gore ? raw : dark(outer, 0.3f));
                chunk(bx + fx.rr_(size), by + fx.rr_(size), hw, hh, col, inner, false, false, gore && !ice, 1f, vx, vy, dx, dy, 1f);
            }
            if (!gore && !skeleton) return;
            int nBone = skeleton ? 5 : (part == Person.CHEST ? 3 : (part == Person.HEAD ? 3 : (part == Person.PELVIS ? 2 : 2)));
            for (int k = 0; k < nBone; k++) {
                bool skull = part == Person.HEAD && !skeleton;
                float hw = skull ? 3.5f + rnd.nextFloat() * 3f : (limb ? 8f : 7f) + rnd.nextFloat() * 5f, hh = skull ? 3f + rnd.nextFloat() * 2f : 1.9f + rnd.nextFloat() * 0.6f;
                int bc = ice ? unchecked((int)0xFFe6f6ffU) : (zombie ? unchecked((int)0xFFcfd2a8U) : bonec);
                chunk(bx + fx.rr_(size), by + fx.rr_(size), hw, hh, bc, 0, false, true, false, 0.8f, vx, vy, dx, dy, 1.1f);
            }
            if (skeleton || ice) return;
            // organs and the brain
            if (part == Person.CHEST) {
                chunk(bx + fx.rr_(8f), by + fx.rr_(8f), 6.5f, 6.5f, zombie ? unchecked((int)0xFF5a7a2aU) : unchecked((int)0xFF8f1d2cU), raw, true, false, true, 1.1f, vx, vy, dx, dy, 0.9f);
                chunk(bx + fx.rr_(8f), by + fx.rr_(8f), 5.5f, 5.5f, zombie ? unchecked((int)0xFF6e8a3aU) : unchecked((int)0xFF7a3b5aU), raw, true, false, true, 1.1f, vx, vy, dx, dy, 0.9f);
            } else if (part == Person.HEAD) {
                chunk(bx, by, 7f, 7f, zombie ? unchecked((int)0xFF8aa86aU) : unchecked((int)0xFFd98aa0U), raw, true, false, true, 1f, vx, vy, dx, dy, 0.8f);
            } else if (part == Person.PELVIS) {
                chunk(bx + fx.rr_(6f), by + fx.rr_(6f), 5.5f, 5.5f, zombie ? unchecked((int)0xFF6e8a3aU) : unchecked((int)0xFFc2606aU), raw, true, false, true, 1.1f, vx, vy, dx, dy, 0.9f);
            }
        }

        // ------------------------------------------------------------------------------ animals ---

        /** Damage to an animal: blood, a yelp, and it dies at zero (bursts far below). */
        public void hurtAnimal(Prop a, float dmg, float x, float y, float dx, float dy) {
            if (a.removed || dmg <= 0f) return;
            a.hp -= dmg;
            a.flash = 0.12f;
            fx.bloodA = unchecked((int)0xFFa80f18U); fx.bloodB = unchecked((int)0xFF5e0a0fU);
            if (dmg > 3f) fx.blood(x, y, dx, dy, (int) Math.min(8, 2 + dmg * 0.2f));
            int k = a.type - Items.DOG;
            if (!a.dead && dmg > 4f && a.barkT <= 0f) { a.barkT = 0.5f; if (sfx != null) sfx.call(Fauna.PITCH[k] * 1.35f); }
            if (!a.dead && a.hp <= 0f) { a.dead = true; a.mood = "Muerto"; a.meal = null; if (sfx != null) sfx.crunch(); }
            if (a.hp < -Prop.ANIMAL_HP[k] * 1.3f) gibAnimal(a, dx, dy);
        }

        public void gibAnimal(Prop a, float dx, float dy) {
            if (a.removed) return;
            RB b = a.main();
            float[] d = a.dims();
            float bx = b.x, by = b.y, vx = b.vx, vy = b.vy;
            remove(a);
            stats.gibs++;
            int n = a.type == Items.RAT ? 3 : 6;
            for (int k = 0; k < n && canAdd(); k++) {
                float hw = Math.max(3f, d[1] * (0.4f + rnd.nextFloat() * 0.4f)), hh = Math.max(2.5f, hw * (0.6f + rnd.nextFloat() * 0.4f));
                int col = !fx.gore ? (k % 2 == 0 ? a.color : dark(a.color, 0.25f)) : (k % 3 == 0 ? a.color : (k % 3 == 1 ? unchecked((int)0xFFa3202aU) : unchecked((int)0xFFc94a52U)));
                Prop c = Prop.block(bx + fx.rr_(d[0]), by + fx.rr_(d[1]), hw, hh, col, 1f, false);
                c.gib = true;
                c.register(sim);
                RB r = c.main();
                r.setAngle(rnd.nextFloat() * 6.283f);
                float sp = 240f + rnd.nextFloat() * 380f, ang = rnd.nextFloat() * 6.283f;
                r.vx = vx * 0.5f + dx * 200f + (float) Math.cos(ang) * sp;
                r.vy = vy * 0.5f + dy * 200f + (float) Math.sin(ang) * sp - 150f;
                add(c);
                keepChunk(c);
            }
            fx.bloodA = unchecked((int)0xFFa80f18U); fx.bloodB = unchecked((int)0xFF5e0a0fU);
            fx.blood(bx, by, 0f, -0.4f, 24);
            if (sfx != null) { sfx.splat(); sfx.crunch(); }
            rumble += 0.25f;
        }

        /** A poop is squashed: brown splat. */
        public void squish(Prop q) {
            if (q.removed) return;
            for (int i = 0; i < 10; i++) fx.add(Fx.BLOOD, q.cx(), q.cy(), fx.rr_(220), -fx.rf() * 220f, 1.2f, 2.5f + fx.rf() * 2.5f, i % 2 == 0 ? unchecked((int)0xFF6b4423U) : unchecked((int)0xFF4f3018U));
            if (sfx != null) sfx.splat();
            remove(q);
        }

        private static int dark(int c, float t) { return Renderer.dark(c, t); }
        private static bool flesh(Person p) { return p.fleshy(); }

        public void keepChunk(Prop c) {
            chunks.add(c);
            while (chunks.size() > MAX_CHUNKS) {
                Prop o = chunks.remove(0);
                if (!o.removed) { fx.debris(o.cx(), o.cy(), 2, o.color, 80f); remove(o); }
            }
        }

        /** Things that splinter and break apart (not machines, bombs or static pillars). */
        public static bool breakable(Prop q) {
            if (q.bodies.isEmpty() || q.main().isStatic) return false;
            if (q.color == Build.GLASS && q.frag) return false;       // shards do not break again
            return q.type == Items.CRATE || q.type == Items.BIGCRATE || q.type == Items.PLANK || q.type == Items.BLOCK || q.type == Items.GLASS;
        }

        /** How much damage a breakable thing takes before it breaks. */
        public static float toughness(Prop q) {
            float base_;
            if (q.gib) base_ = 30f;
            else if (q.color == Build.GLASS) base_ = 30f;
            else if (q.type == Items.CRATE) base_ = 70f;
            else if (q.type == Items.BIGCRATE) base_ = 120f;
            else if (q.type == Items.PLANK) base_ = 80f;
            else if (q.color == Build.STEEL) base_ = 420f;
            else if (q.color == Build.CONCRETE) base_ = 230f;
            else if (q.color == Build.BRICK) base_ = 150f;
            else base_ = 85f;
            float size = Math.max(q.hw, q.hh);
            return base_ * Math.max(0.3f, Math.min(1f, size / 30f));
        }

        /** Adds damage to a breakable thing; it breaks when it has taken enough. */
        public void wear(Prop q, float dmg, bool deferred) {
            if (q.removed || dmg <= 0f || !breakable(q)) return;
            q.wear += dmg;
            if (q.wear < toughness(q)) return;
            if (deferred) { if (!breakQ.contains(q)) breakQ.add(q); }
            else fracture(q, q.cx(), q.cy());
        }

        /** Destruction engine: a crack (or a dent on metal) where something hit, in the thing's own frame. */
        public void crack(Prop q, float wx, float wy, float amount) {
            if (q.bodies.isEmpty() || amount <= 0f) return;
            RB b = q.main();
            float ex = wx - b.x, ey = wy - b.y;
            float u = ex * b.c + ey * b.s, v = -ex * b.s + ey * b.c;
            u = Math.max(-q.hw * 0.9f, Math.min(q.hw * 0.9f, u));
            v = Math.max(-q.hh * 0.9f, Math.min(q.hh * 0.9f, v));
            q.impX = wx; q.impY = wy;
            // chips fly off the spot (not off metal): the harder the hit the more
            bool metal = q.type == Items.BARREL || q.type == Items.XBARREL || q.type == Items.STEEL || q.type == Items.FRIDGE || q.color == Build.STEEL;
            if (!metal && amount > 0.06f) fx.debris(wx, wy, 1 + (int) Math.min(4f, amount * 6f), q.color == Build.GLASS ? unchecked((int)0xFFd8efffU) : q.color, 150f + amount * 200f);
            // a hit next to an old crack makes it longer
            for (int i = 0; i < q.ncr; i++) {
                if (Math.abs(q.crU[i] - u) < 10f && Math.abs(q.crV[i] - v) < 10f) { q.crS[i] = Math.min(1.6f, q.crS[i] + amount); return; }
            }
            int slot = q.ncr < Prop.MAXCRACK ? q.ncr++ : rnd.nextInt(Prop.MAXCRACK);
            q.crU[slot] = u; q.crV[slot] = v; q.crS[slot] = Math.min(1.6f, amount);
        }

        /**
         * Breaks a block/crate/plank: the piece is cut again and again around the point of impact, so the pieces
         * are small and fly fast where it was hit and large and slow far from it; tiny bits become splinters.
         */
        public void fracture(Prop q, float ix, float iy) {
            if (q.removed) return;
            if (!Float.isNaN(q.impX)) { ix = q.impX; iy = q.impY; }
            RB b = q.main();
            float hw = q.hw, hh = q.hh, bx = b.x, by = b.y, a = b.a, vx = b.vx, vy = b.vy, w = b.w;
            bool burning = q.burning;
            int col = q.color;
            bool brick = col == Build.BRICK || col == Build.CONCRETE, steel = col == Build.STEEL;
            remove(q);
            stats.broken++;
            if (!q.gib) stats.destroyed++;
            if (q.isStruct) fx.dust(bx, by, Math.min(70f, (hw + hh) * 0.5f), Math.min(8, 2 + (int) ((hw + hh) / 30f)));
            if (col == Build.GLASS) { shatterGlass(q, bx, by, a, hw, hh, vx, vy, w, ix, iy); return; }
            // splinters and dust by material
            int nsp = Math.min(16, 4 + (int) ((hw + hh) * 0.15f));
            for (int k = 0; k < nsp; k++) {
                float an = rnd.nextFloat() * 6.283f, sp = 120f + rnd.nextFloat() * 300f;
                fx.add(Fx.DEBRIS, ix + fx.rr_(hw * 0.4f), iy + fx.rr_(hh * 0.4f), (float) Math.cos(an) * sp, (float) Math.sin(an) * sp - 140f, 0.9f + rnd.nextFloat() * 0.8f,
                        brick ? 2.5f + rnd.nextFloat() * 3f : 1.6f + rnd.nextFloat() * 2.4f, k % 3 == 0 ? Renderer.dark(col, 0.25f) : col);
            }
            fx.smoke(ix, iy, brick ? 16f : 9f, brick ? unchecked((int)0xFFb09a8aU) : (steel ? unchecked((int)0xFF7a7a7aU) : unchecked((int)0xFFa89a86U)));
            if (brick) for (int k = 0; k < 4; k++) fx.smoke(bx + fx.rr_(hw), by + fx.rr_(hh), 10f, unchecked((int)0xFFc4ae9cU));
            if (steel) fx.sparks(ix, iy, 12, unchecked((int)0xFFffd25aU));
            if (sfx != null) sfx.crunch();
            rumble += 0.1f;
            if (Math.max(hw, hh) < 9f || q.gib) return;
            // pieces as rectangles in the local frame: l, t, r, b
            float ca = (float) Math.cos(a), sa = (float) Math.sin(a);
            float lix = (ix - bx) * ca + (iy - by) * sa, liy = -(ix - bx) * sa + (iy - by) * ca;
            lix = Math.max(-hw, Math.min(hw, lix)); liy = Math.max(-hh, Math.min(hh, liy));
            float[][] pc = new float[10][];
            int n = 1;
            pc[0] = new float[]{-hw, -hh, hw, hh};
            int cuts = Math.min(7, 2 + (int) ((hw + hh) / 26f));
            for (int c = 0; c < cuts && n < pc.Length; c++) {
                // cut the piece that holds the impact point most of the time, otherwise the biggest one
                int pick = 0;
                float best = -1f;
                bool nearHit = rnd.nextFloat() < 0.65f;
                for (int k = 0; k < n; k++) {
                    float[] rk = pc[k];
                    float area = (rk[2] - rk[0]) * (rk[3] - rk[1]);
                    bool holds = lix >= rk[0] - 0.5f && lix <= rk[2] + 0.5f && liy >= rk[1] - 0.5f && liy <= rk[3] + 0.5f;
                    float score = nearHit ? (holds ? area + 1e6f : area) : area;
                    if (score > best) { best = score; pick = k; }
                }
                float[] r = pc[pick];
                float pw = r[2] - r[0], ph = r[3] - r[1];
                if (Math.max(pw, ph) < 14f) continue;
                bool vertical = pw > ph * (0.8f + rnd.nextFloat() * 0.5f);
                float lo = vertical ? r[0] : r[1], len = vertical ? pw : ph, at = vertical ? lix : liy;
                float f = 0.3f + rnd.nextFloat() * 0.4f;
                if (at > lo && at < lo + len) f = f * 0.5f + Math.max(0.2f, Math.min(0.8f, (at - lo) / len)) * 0.5f;
                float cut = lo + len * f;
                float[] other = r.clone();
                if (vertical) { r[2] = cut; other[0] = cut; } else { r[3] = cut; other[1] = cut; }
                pc[n++] = other;
            }
            for (int k = 0; k < n; k++) {
                if (!canAdd()) return;
                float[] r = pc[k];
                float pw = (r[2] - r[0]) * 0.5f, ph = (r[3] - r[1]) * 0.5f;
                float lx = (r[0] + r[2]) * 0.5f, ly = (r[1] + r[3]) * 0.5f;
                float wx = bx + ca * lx - sa * ly, wy = by + sa * lx + ca * ly;
                if (Math.min(pw, ph) < 2.5f || pw * ph < 30f) { fx.debris(wx, wy, 2, col, 220f); continue; }
                float jw = pw * (0.9f + rnd.nextFloat() * 0.08f), jh = ph * (0.9f + rnd.nextFloat() * 0.08f);
                Prop f = Prop.block(wx, wy, jw, jh, col, q.type == Items.BLOCK ? q.dens : 0.7f, q.flammable);
                f.frag = true;
                f.register(sim);
                RB rb = f.main();
                rb.setAngle(a + (rnd.nextFloat() - 0.5f) * 0.25f);
                float ox = wx - ix, oy = wy - iy, ol = (float) Math.sqrt(ox * ox + oy * oy) + 1f;
                // close to the hit: fast; far: just falls apart
                float kick = (60f + rnd.nextFloat() * 120f) + 5200f / (ol + 25f);
                rb.vx = vx - w * (wy - by) + ox / ol * kick;
                rb.vy = vy + w * (wx - bx) + oy / ol * kick - 40f;
                rb.w = w + fx.rr_(8f);
                // the broken edges keep a crack or two
                f.ncr = 1; f.crU[0] = (ix - wx) * ca + (iy - wy) * sa; f.crV[0] = -(ix - wx) * sa + (iy - wy) * ca;
                f.crU[0] = Math.max(-jw, Math.min(jw, f.crU[0])); f.crV[0] = Math.max(-jh, Math.min(jh, f.crV[0])); f.crS[0] = 0.5f;
                add(f);
                keepChunk(f);
                if (burning) ignite(f);
            }
        }

        /** Glass: many thin shards with sharp edges that spray out from the hit and cut whoever they hit; a glittering burst. */
        private void shatterGlass(Prop q, float bx, float by, float a, float hw, float hh, float vx, float vy, float w, float ix, float iy) {
            stats.glass++;
            float ca = (float) Math.cos(a), sa = (float) Math.sin(a);
            int n = Math.min(16, 6 + (int) ((hw + hh) * 0.1f));
            for (int k = 0; k < n && canAdd(); k++) {
                float lx = (rnd.nextFloat() * 2f - 1f) * hw, ly = (rnd.nextFloat() * 2f - 1f) * hh;
                float wx = bx + ca * lx - sa * ly, wy = by + sa * lx + ca * ly;
                float sw = 2.5f + rnd.nextFloat() * Math.min(9f, Math.max(hw, hh) * 0.2f), sh = 1.1f + rnd.nextFloat() * 1.3f;
                Prop f = Prop.block(wx, wy, sw, sh, Build.GLASS, 0.4f, false);
                f.frag = true; f.sharp = true;
                f.register(sim);
                RB rb = f.main();
                rb.setAngle(rnd.nextFloat() * 6.283f);
                float ox = wx - ix, oy = wy - iy, ol = (float) Math.sqrt(ox * ox + oy * oy) + 1f;
                float kick = 120f + rnd.nextFloat() * 260f + 3600f / (ol + 30f);
                rb.vx = vx - w * (wy - by) + ox / ol * kick;
                rb.vy = vy + w * (wx - bx) + oy / ol * kick - 60f;
                rb.w = rnd.nextFloat() * 20f - 10f;
                add(f);
                keepChunk(f);
            }
            for (int k = 0; k < 18; k++) {
                float an = rnd.nextFloat() * 6.283f, sp = 120f + rnd.nextFloat() * 420f;
                fx.add(Fx.DEBRIS, ix + fx.rr_(hw), iy + fx.rr_(hh), (float) Math.cos(an) * sp, (float) Math.sin(an) * sp - 160f, 0.8f + rnd.nextFloat() * 0.9f, 1.5f + rnd.nextFloat() * 2.2f, k % 3 == 0 ? unchecked((int)0xFFffffffU) : unchecked((int)0xFFbfe3f7U));
            }
            fx.sparks(ix, iy, 8, unchecked((int)0xFFeaf6ffU));
            if (sfx != null) { sfx.pop(); sfx.crunch(); }
            rumble += 0.08f;
        }

        public void pop(Prop q) {
            fx.sparks(q.cx(), q.cy(), 8, q.color);
            fx.debris(q.cx(), q.cy(), 6, q.color, 220f);
            if (sfx != null) sfx.pop();
            remove(q);
        }

        public void smash(Prop q) {
            stats.melons++;
            fx.debris(q.cx(), q.cy(), 8, unchecked((int)0xFF3f9a3cU), 300f);
            for (int i = 0; i < 12; i++) fx.add(Fx.BLOOD, q.cx(), q.cy(), fx.rr_(300), -fx.rf() * 300f, 1.3f, 3f + fx.rf() * 3f, unchecked((int)0xFFd8344aU));
            if (sfx != null) sfx.splat();
            remove(q);
        }

        // props ---------------------------------------------------------------------------------------

        private void updateProp(Prop q, float dt) {
            if (q.flash > 0f) q.flash -= dt;
            if (!q.bodies.isEmpty()) { RB r = q.main(); q.lastSp = (float) Math.hypot(r.vx, r.vy) + Math.abs(r.w) * Math.max(q.hw, q.hh); }
            q.age += dt;
            RB m = q.main();
            if (q.fuse >= 0f) {
                q.fuse -= dt;
                if (rnd.nextFloat() < 0.6f && q.type != Items.TNT && q.type != Items.XBARREL)
                    fx.add(Fx.SPARK, m.x, m.y - 8f, fx.rr_(120), -120f - fx.rf() * 160f, 0.3f, 2f, unchecked((int)0xFFffc83dU));
                if (q.fuse <= 0f) {
                    float bx = m.x, by = m.y;
                    bool fire = q.type == Items.XBARREL;
                    float r = q.blastR, pw = q.blastPow, dm = q.blastDmg;
                    remove(q);
                    explode(bx, by, r, pw, dm, true);
                    if (fire) for (int k = 0; k < 6; k++) fx.flame(bx + fx.rr_(60), by + fx.rr_(30), 18f);
                    return;
                }
            }
            if (q.type == Items.THRUSTER && q.thrust) {
                if (rnd.nextFloat() < dt * 60f) {
                    float ux = (float) Math.sin(m.a), uy = (float) -Math.cos(m.a);
                    fx.add(Fx.FLAME, m.x - ux * 20f, m.y - uy * 20f, -ux * 160f + fx.rr_(40), -uy * 160f + fx.rr_(40), 0.3f, 9f, unchecked((int)0xFFffa040U));
                }
            }
            if (q.type == Items.GUN_MG && q.firing) {
                q.fireCd -= dt;
                if (q.fireCd <= 0f) { q.fireCd = 0.075f; fireGun(q); }
            }
            if (q.machine()) Mind.machineThink(this, q, dt);
            if (q.gib && q.bloody && fx.gore) {
                // gore V5: chunks sliding on the floor leave a smear
                if (m.y + q.hh >= sim.floorY - 5f && q.lastSp > 90f && rnd.nextFloat() < dt * 16f) fx.stain(m.x, 3f + Math.min(5f, q.lastSp * 0.01f), Renderer.alpha(q.color2, 0.8f));
                if (q.splatT > 0f) q.splatT -= dt;
                if (q.lastSp > 160f && rnd.nextFloat() < dt * 22f)       // a trail of drops while it flies
                    fx.add(Fx.BLOOD, m.x, m.y, m.vx * 0.12f + fx.rr_(30f), m.vy * 0.12f + fx.rr_(30f), 1.4f, 2f + fx.rf() * 2.2f, q.color2);
            }
            if (q.type == Items.FRIDGE) fridgeTick(q, dt);
            if (q.fixedMachine()) Machines.update(this, q, dt);
            if (q.isStruct && q.relT >= 0f && m.frozen) {                 // unsupported: it lets go
                q.relT -= dt;
                if (q.relT <= 0f) {
                    m.setFrozen(false);
                    m.w += fx.rr_(0.8f);
                    fx.dust(q.cx(), q.cy(), Math.min(60f, Math.max(q.hw, q.hh) * 0.6f), 2);
                    stats.destroyed++;
                }
            }
            if (Items.isTrap(q.type)) Traps.update(this, q, dt);
            if (q.animal()) Fauna.think(this, q, dt);
            else if (q.type == Items.POOP) Fauna.stink(this, q, dt);
        }

        /** Fires a gun object along its barrel with recoil. */
        public void fireGun(Prop g) {
            RB b = g.main();
            float hl = g.hw;
            float dx = (float) Math.cos(b.a), dy = (float) Math.sin(b.a);
            float ox = b.x + dx * (hl + 8f), oy = b.y + dy * (hl + 8f);
            int k = (int) g.param;
            switch (k) {
                case 0: shoot(g, ox, oy, dx, dy, 24f, 950f, 1); break;
                case 1: shoot(g, ox, oy, dx, dy, 40f, 1600f, 3); break;
                default: {
                    float ang = (float) Math.atan2(dy, dx) + (rnd.nextFloat() - 0.5f) * 0.07f;
                    shoot(g, ox, oy, (float) Math.cos(ang), (float) Math.sin(ang), 14f, 600f, 1);
                }
             break; }
            float rec = (k == 1 ? 9e5f : (k == 2 ? 3e5f : 5e5f));
            b.applyImpulse(-dx * rec, -dy * rec, b.x, b.y);
            b.w += -(dx > 0 ? 1f : -1f) * 0.8f * (k == 1 ? 3f : 1f);
            fx.add(Fx.GLOW, ox, oy, 0, 0, 0.06f, 16f, unchecked((int)0xFFfff0b0U));
            fx.sparks(ox, oy, 3, unchecked((int)0xFFffd25aU));
            if (sfx != null) sfx.shot();
            rumble += 0.06f;
        }

        public void damageMachine(Prop m, float dmg) {
            if (m.dead || dmg <= 0f) return;
            m.hp -= dmg;
            m.flash = 0.12f;
            fx.sparks(m.cx(), m.cy(), 4, unchecked((int)0xFFffd25aU));
            if (m.hp <= 0f) {
                m.dead = true; m.on = false; m.thrust = false;
                m.mood = "Averiado";
                fx.sparks(m.cx(), m.cy(), 18, unchecked((int)0xFFffd25aU));
                fx.smoke(m.cx(), m.cy(), 16f, unchecked((int)0xFF3c3c3cU));
                fx.add(Fx.GLOW, m.cx(), m.cy(), 0, 0, 0.25f, 70f, unchecked((int)0xFFffb060U));
                if (sfx != null) sfx.boom(0.15f);
                stats.machinesDown++;
                if (m.type == Items.DRONE) foreach (RB b in m.bodies) b.gravScale = 1f;
                if (m.aimJoint != null) m.aimJoint.muscle = false;
            }
        }

        /** The shock wave snaps construction welds near the blast, the nearer the likelier. */
        private void shockWelds(float x, float y, float R) {
            for (int i = sim.joints.size() - 1; i >= 0; i--) {
                Joint j = sim.joints.get(i);
                if (j.tag != Build.TAG || j.removed) continue;
                float dx = j.anchorBX() - x, dy = j.anchorBY() - y;
                float f = 1f - (float) Math.sqrt(dx * dx + dy * dy) / R;
                if (f <= 0.1f || rnd.nextFloat() >= (f - 0.05f) * 1.6f) continue;
                sim.remove(j);
                jointBroken(j);
            }
        }

        // ------------------------------------------------------------------------------- explosions --

        /** Blast: damages and throws everything, sets fire, detonates neighbours. power is a speed in units/s. */
        public void explode(float x, float y, float R, float power, float dmg, bool chain) {
            fx.explosion(x, y, R);
            rumble += Math.min(1.2f, R / 450f);
            stats.explosions++;
            stats.recentBooms++;
            stats.recentT = 2f;
            if (sfx != null) sfx.boom(Math.min(1f, R / 600f));
            sim.blast(x, y, R, power);
            shockWelds(x, y, R);
            // a blast near the ground burns it black
            if (y > sim.floorY - R * 0.9f) {
                fx.stain(x, R * 1.1f, unchecked((int)0xE6120e0bU));
                fx.stain(x + fx.rr_(R * 0.3f), R * 0.6f, unchecked((int)0xE61c130dU));
            }
            alarm(x, y, R * 2f + 300f, 6f);
            Ent[] list = snapshot();
            int n = ents.size();
            for (int i = n - 1; i >= 0; i--) {
                Ent e = list[i];
                list[i] = null;
                if (e == null || e.removed) continue;
                float dx = e.cx() - x, dy = e.cy() - y;
                float d = (float) Math.sqrt(dx * dx + dy * dy);
                if (d - e.radius() > R) continue;
                float f = Math.max(0f, 1f - Math.max(0f, d - e.radius() * 0.6f) / R);
                if (f <= 0.02f) continue;
                if (e is Prop) {
                    Prop q = (Prop) e;
                    if (q.type == Items.BALLOON) { if (f > 0.1f) pop(q); continue; }
                    if (q.type == Items.MELON) { if (f > 0.15f) smash(q); continue; }
                    if (q.type == Items.POOP) { if (f > 0.15f) squish(q); continue; }
                    if (q.animal()) {
                        if (f > 0.7f && dmg > 55f) gibAnimal(q, dx / (d + 1f), dy / (d + 1f));
                        else { hurtAnimal(q, dmg * f * f * 1.6f, q.cx(), q.cy(), dx / (d + 1f), dy / (d + 1f)); if (f > 0.35f) ignite(q); }
                        continue;
                    }
                    if (q.explosive && q.fuse < 0f && f > 0.15f) q.fuse = 0.06f + rnd.nextFloat() * 0.25f;
                    if (q.flammable && f > 0.35f) ignite(q);
                    if (q.machine()) damageMachine(q, dmg * f * f * 2f);
                    if (q.isStruct && f > 0.42f && breakable(q)) { q.impX = x; q.impY = y; wear(q, toughness(q) * 3f, true); }   // the blast carves a hole
                    if (f > 0.1f && breakable(q)) crack(q, x, y, f);
                    else if (f > 0.1f && (q.type == Items.BARREL || q.type == Items.STEEL || q.type == Items.FRIDGE)) crack(q, x, y, f * 0.6f);
                    if (f > 0.1f) wear(q, dmg * f * f * 2.6f, false);
                } else {
                    Person p = (Person) e;
                    if (p.flammable && f > 0.35f) ignite(p);
                    for (int part = 0; part < Person.NPARTS; part++) {
                        RB b = p.rb[part];
                        float px = b.x - x, py = b.y - y, pd = (float) Math.sqrt(px * px + py * py);
                        float pf = Math.max(0f, 1f - pd / R);
                        if (pf <= 0.02f) continue;
                        if (p.gibbed[part]) continue;
                        float hd = dmg * pf * pf * 0.9f;
                        if (hd > 8f) wound(p, part, Person.W_BURN, b.x - px / (pd + 1f) * 8f, b.y - py / (pd + 1f) * 8f, px, py, 4f + Math.min(8f, hd * 0.12f));
                        // point blank: the part bursts
                        if (hd > 55f && rnd.nextFloat() < (pf - 0.7f) * 2.2f) { gib(p, part, px / (pd + 1f), py / (pd + 1f)); continue; }
                        hurt(p, part, hd, b.x, b.y, px / (pd + 1f), py / (pd + 1f));
                    }
                    if (f > 0.4f) {
                        for (int j = 0; j < Person.NJOINTS; j++) {
                            if (p.severed[j] || j == Person.WAIST) continue;
                            if (rnd.nextFloat() < (f - 0.3f) * 1.25f) {
                                RB b = p.rb[Person.PART_JOINT_CHILD[j]];
                                sever(p, j, b.x, b.y);
                            }
                        }
                    }
                    if (f > 0.7f && !p.dead) kill(p);
                }
            }
        }

        // ------------------------------------------------------------------------------------ fire ---

        public void ignite(Ent e) {
            if (e.burning || !e.flammable) return;
            if (e is Prop && ((Prop) e).type == Items.C4) return;
            e.burning = true;
            e.burnT = e is Person ? 16f : (e is Prop && ((Prop) e).explosive ? 1f : 9f);
            if (e is Prop && ((Prop) e).explosive && ((Prop) e).fuse < 0f) ((Prop) e).fuse = 0.4f + rnd.nextFloat() * 0.5f;
        }

        private void updateBurning(Ent e, float dt) {
            e.burnT -= dt;
            e.charT = Math.min(0.85f, e.charT + dt * 0.07f);
            int nb = e.bodies.size();
            if (nb == 0) { e.burning = false; return; }
            float rate = e is Person ? 70f : 45f;
            int cnt = (int) (rate * dt + rnd.nextFloat());
            for (int k = 0; k < cnt; k++) {
                RB b = e.bodies.get(rnd.nextInt(nb));
                fx.flame(b.x, b.y, 7f + (b.shapes.isEmpty() ? 6f : b.shapes.get(0).reach() * 0.3f));
            }
            if (rnd.nextFloat() < 14f * dt) { RB b = e.bodies.get(rnd.nextInt(nb)); fx.smoke(b.x, b.y - 8f, 6f, unchecked((int)0xFF3c3c3cU)); }
            if (e is Person) {
                Person p = (Person) e;
                if (!p.dead) { p.blood -= 4.5f * dt; if (p.blood <= 0f) kill(p); }
            } else if (((Prop) e).animal()) {
                Prop a = (Prop) e;
                a.hp -= 6f * dt;
                if (!a.dead && a.hp <= 0f) { a.dead = true; a.mood = "Muerto"; }
            }
            if (e.burnT <= 0f) e.burning = false;
        }

        private float spreadT;

        private void spreadFire() {
            int n = ents.size();
            for (int i = 0; i < n; i++) {
                Ent a = ents.get(i);
                if (!a.burning) continue;
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    Ent b = ents.get(j);
                    if (b.burning || !b.flammable) continue;
                    float dx = a.cx() - b.cx(), dy = a.cy() - b.cy(), rr = a.radius() + b.radius() + 14f;
                    if (dx * dx + dy * dy > rr * rr) continue;
                    bool near = false;
                    for (int u = 0; u < a.bodies.size() && !near; u++) {
                        RB p = a.bodies.get(u);
                        for (int v = 0; v < b.bodies.size(); v++) {
                            RB q = b.bodies.get(v);
                            float ex = p.x - q.x, ey = p.y - q.y;
                            float r = (p.shapes.isEmpty() ? 10f : p.shapes.get(0).reach()) + (q.shapes.isEmpty() ? 10f : q.shapes.get(0).reach()) + 16f;
                            if (ex * ex + ey * ey < r * r) { near = true; break; }
                        }
                    }
                    if (near && rnd.nextFloat() < 0.28f) ignite(b);
                }
            }
        }

        // ------------------------------------------------------------------------------- projectiles --

        private void tracer(float x0, float y0, float x1, float y1) {
            int i = trNext;
            trNext = (trNext + 1) & 7;
            trX0[i] = x0; trY0[i] = y0; trX1[i] = x1; trY1[i] = y1; trT[i] = 0.07f;
        }

        /** Fires a bullet. Returns the distance travelled. The shooter's own parts are ignored. */
        public float shoot(Ent shooter, float x, float y, float dx, float dy, float dmg, float impulse, int pierce) {
            float l = (float) Math.sqrt(dx * dx + dy * dy);
            dx /= l; dy /= l;
            float tEnd = sim.rayRoom(x, y, dx, dy, 5200f);
            bool hitRoom = true;
            JList<Sim.Hit> hs = sim.ray(x, y, dx, dy, tEnd);
            int pierced = 0;
            float stopT = tEnd;
            for (int i = 0; i < hs.size(); i++) {
                Sim.Hit h = hs.get(i);
                Object u = h.shape.body.user;
                if (u == shooter && shooter != null) continue;
                float hx = x + dx * h.t, hy = y + dy * h.t;
                applyBullet(h.shape, u, hx, hy, dx, dy, dmg, impulse, shooter);
                if (++pierced >= pierce) { stopT = h.t; hitRoom = false; break; }
            }
            float ix = x + dx * stopT, iy = y + dy * stopT;
            fx.add(Fx.GLOW, x, y, 0, 0, 0.05f, 14f, unchecked((int)0xFFfff0b0U));
            tracer(x, y, ix, iy);
            if (hitRoom) fx.sparks(ix, iy, 6, unchecked((int)0xFFffe08aU));
            return stopT;
        }

        private void applyBullet(Shape s, Object u, float hx, float hy, float dx, float dy, float dmg, float impulse, Ent shooter) {
            RB b = s.body;
            float J = impulse * 350f;
            if (u is Prop) {
                Prop q = (Prop) u;
                if (q.type == Items.BALLOON) { pop(q); return; }
                if (q.type == Items.MELON) { smash(q); return; }
                if (q.type == Items.POOP) { squish(q); return; }
                if (q.animal()) { b.applyImpulse(dx * J, dy * J, hx, hy); hurtAnimal(q, dmg * 1.4f, hx, hy, dx, dy); if (sfx != null) sfx.splat(); return; }
                if (q.explosive && q.fuse < 0f && q.type != Items.GRENADE && q.type != Items.DYNAMITE) q.fuse = 0.05f;
                if (q.machine()) damageMachine(q, dmg * 1.1f);
                b.applyImpulse(dx * J, dy * J, hx, hy);
                fx.sparks(hx, hy, 5, q.type == Items.CRATE || q.type == Items.PLANK ? unchecked((int)0xFFe8c48aU) : unchecked((int)0xFFffe08aU));
                if (q.type == Items.CRATE || q.type == Items.PLANK) fx.debris(hx, hy, 2, q.color, 180f);
                if (breakable(q)) { fx.debris(hx, hy, 2, q.color, 160f); crack(q, hx, hy, dmg * 1.3f / Math.max(20f, toughness(q))); wear(q, dmg * 1.3f, false); }
                else if (q.type == Items.BARREL || q.type == Items.XBARREL || q.type == Items.STEEL || q.type == Items.FRIDGE) crack(q, hx, hy, 0.35f);
            } else if (u is Person) {
                Person p = (Person) u;
                int part = Person.partOf(p, s);
                b.applyImpulse(dx * J, dy * J, hx, hy);
                bloodStyle(p);
                fx.blood(hx, hy, dx, dy, 7);
                if (part < 0) return;
                if (p.frozenT > 0f) { bool core = part == Person.HEAD || part == Person.CHEST; gib(p, part, dx, dy); if (core) Machines.shatter(this, p); return; }
                wound(p, part, Person.W_HOLE, hx, hy, dx, dy, 2.2f + dmg * 0.03f);
                if (p.organic()) p.bleed[part] = Math.max(p.bleed[part], 6f);
                // heavy rounds burst heads
                if (part == Person.HEAD && dmg >= 40f && rnd.nextFloat() < 0.6f) { bool alive = !p.dead; gib(p, part, dx, dy); if (alive) { stats.headshots++; if (shooter != null && !(shooter is Person && ((Person) shooter).kind == Person.THUG)) stats.aiKills++; } return; }
                bool wasAlive = !p.dead;
                if (part == Person.HEAD && wasAlive) {
                    stats.headshots++;
                    hurt(p, part, 140f, hx, hy, dx, dy);
                    kill(p);
                    fx.blood(hx, hy, dx, dy, 12);
                } else {
                    hurt(p, part, dmg * 1.2f, hx, hy, dx, dy);
                }
                if (sfx != null) sfx.splat();
                if (wasAlive && p.dead && shooter != null && !(shooter is Person && ((Person) shooter).kind == Person.THUG)) stats.aiKills++;
            }
        }

        public void shotgun(float x, float y, float dx, float dy) {
            float base_ = (float) Math.atan2(dy, dx);
            for (int i = 0; i < 9; i++) {
                float a = base_ + (rnd.nextFloat() - 0.5f) * 0.28f;
                shoot(null, x, y, (float) Math.cos(a), (float) Math.sin(a), 9f, 420f, 1);
            }
        }

        public void launchRocket(float x, float y, float dx, float dy, Ent owner) {
            if (rockets.size() > 8) return;
            Rocket r = new Rocket();
            float l = (float) Math.sqrt(dx * dx + dy * dy);
            r.x = x; r.y = y; r.vx = dx / l * 1250f; r.vy = dy / l * 1250f; r.life = 4f; r.owner = owner;
            rockets.add(r);
            if (sfx != null) sfx.launch();
        }

        private void updateRockets(float dt) {
            for (int i = rockets.size() - 1; i >= 0; i--) {
                Rocket r = rockets.get(i);
                r.life -= dt;
                float sp = (float) Math.sqrt(r.vx * r.vx + r.vy * r.vy);
                float dx = r.vx / sp, dy = r.vy / sp, step = sp * dt;
                bool boom = r.life <= 0f;
                float hx = r.x + dx * step, hy = r.y + dy * step;
                JList<Sim.Hit> hs = sim.ray(r.x, r.y, dx, dy, step);
                for (int k = 0; k < hs.size(); k++) {
                    if (hs.get(k).shape.body.user == r.owner && r.owner != null) continue;
                    hx = r.x + dx * hs.get(k).t; hy = r.y + dy * hs.get(k).t; boom = true; break;
                }
                float room = sim.rayRoom(r.x, r.y, dx, dy, step + 1f);
                if (room < step) { hx = r.x + dx * room; hy = r.y + dy * room; boom = true; }
                fx.add(Fx.SMOKE, r.x, r.y, fx.rr_(30), fx.rr_(30), 0.7f, 7f, unchecked((int)0xFF9a9a9aU));
                fx.add(Fx.FLAME, r.x, r.y, fx.rr_(40), fx.rr_(40), 0.2f, 7f, unchecked((int)0xFFffa040U));
                r.x = hx; r.y = hy;
                if (boom) { rockets.remove(i); explode(hx, hy, 340f, 2300f, 95f, true); }
            }
        }

        // ------------------------------------------------------------------------------ other fx ----

        public void lightning(float x, float y) {
            float top = sim.ceilY;
            fx.lightning(x + fx.rr_(60), top, x, y);
            if (sfx != null) sfx.zap();
            rumble += 0.6f;
            sim.blast(x, y, 120f, 700f);
            Shape s = sim.pick(x, y, 36f, false);
            if (s != null && s.body.user is Person) {
                Person p = (Person) s.body.user;
                for (int i = 0; i < Person.NPARTS; i++) hurt(p, i, 22f, p.rb[i].x, p.rb[i].y, 0f, -1f);
                ignite(p);
                if (!p.dead && p.blood < 30f) kill(p);
            } else if (s != null && s.body.user is Ent) ignite((Ent) s.body.user);
        }

        public void push(float x, float y) {
            fx.ring(x, y, 280f);
            sim.blast(x, y, 280f, 1400f);
            if (sfx != null) sfx.pop();
        }

        // ------------------------------------------------------------------------------- syringes ----

        public string inject(Person p, int kind) {
            if (kind == Items.SYR_FREEZE) { Machines.freeze(this, p, 25f); fx.add(Fx.GLOW, p.rb[Person.CHEST].x, p.rb[Person.CHEST].y, 0, 0, 0.3f, 26f, unchecked((int)0xFFbfe8ffU)); if (sfx != null) sfx.pop(); return "¡Congelado! Un golpe fuerte y se rompe"; }
            if (p.kind == Person.ROBOT || p.kind == Person.SKELETON) return "No hace efecto: no tiene sangre";
            RB at = p.rb[Person.CHEST];
            int col;
            string msg;
            switch (kind) {
                case Items.SYR_HEAL: heal(p); col = unchecked((int)0xFF6dff8aU); msg = "Curado"; break;
                case Items.SYR_ADRENALINE:
                    if (p.dead) return "Está muerto: usa Resurrección";
                    p.adrenaline = 25f; p.ko = 0f; p.blood = Math.min(p.maxBlood, p.blood + 20f);
                    col = unchecked((int)0xFFffd23fU); msg = "¡Adrenalina!";
                    break;
                case Items.SYR_LIFE:
                    if (!p.dead) return "Todavía está vivo";
                    if (!p.intact()) return "Está hecho pedazos: no hay resurrección";
                    heal(p); p.dead = false; p.ko = 2.5f; p.tone = 0f; p.blood = p.maxBlood * 0.6f;
                    stats.revives++;
                    col = unchecked((int)0xFF7fd1ffU); msg = "¡Ha vuelto a la vida!";
                    break;
                case Items.SYR_ZOMBIE:
                    if (p.kind == Person.ZOMBIE) return "Ya es un zombi";
                    if (!p.intact()) return "Está hecho pedazos: no hay zombi";
                    p.infected = 2.5f; p.bitten = true;
                    col = unchecked((int)0xFF5aa02aU); msg = "Infectado... en unos segundos";
                    break;
                case Items.SYR_ACID: p.acid = 9f; col = unchecked((int)0xFFb6ff3aU); msg = "Ácido en las venas"; break;
                case Items.SYR_FREEZE: Machines.freeze(this, p, 25f); col = unchecked((int)0xFFbfe8ffU); msg = "¡Congelado! Un golpe fuerte y se rompe"; break;
                default:
                    if (p.dead) return "Está muerto";
                    p.ko = 25f; p.tone = 0f; p.adrenaline = 0f;
                    col = unchecked((int)0xFF9a8cffU); msg = "Zzz...";
             break; }
            for (int i = 0; i < 10; i++) fx.add(Fx.SPARK, at.x, at.y, fx.rr_(180), -80f - fx.rf() * 160f, 0.5f, 2.2f, col);
            fx.add(Fx.GLOW, at.x, at.y, 0, 0, 0.3f, 26f, col);
            if (sfx != null) sfx.pop();
            return msg;
        }

        public void heal(Person p) {
            p.blood = p.maxBlood;
            p.burning = false; p.burnT = 0f; p.acid = 0f; p.ko = 0f; p.infected = -1f; p.bitten = false;
            for (int i = 0; i < Person.NPARTS; i++) {
                p.bleed[i] = 0f;
                p.soak[i] *= 0.3f;
                if (p.broken[i]) p.broken[i] = false;
                p.hp[i] = Person.maxHp(p, i);
            }
            p.nw = 0; p.wNext = 0;          // wounds close
            stats.heals++;
        }

        private void updateAcid(Person p, float dt) {
            p.acid -= dt;
            p.blood -= 9f * dt;
            p.charT = Math.min(0.55f, p.charT + dt * 0.05f);
            if (rnd.nextFloat() < dt * 10f) { RB b = p.rb[rnd.nextInt(Person.NPARTS)]; fx.smoke(b.x, b.y, 7f, unchecked((int)0xFF8fd14aU)); }
            if (rnd.nextFloat() < dt * 0.6f) {
                int[] js = {Person.EL_F, Person.EL_B, Person.KNEE_F, Person.KNEE_B, Person.SH_F, Person.SH_B};
                int j = js[rnd.nextInt(js.Length)];
                if (!p.severed[j]) sever(p, j, p.rb[Person.PART_JOINT_CHILD[j]].x, p.rb[Person.PART_JOINT_CHILD[j]].y);
            }
            if (p.blood <= 0f && !p.dead) kill(p);
            if (p.acid <= 0f && p.dead) skeletonize(p);
        }

        public void skeletonize(Person p) {
            p.kind = Person.SKELETON;
            p.item = Items.SKELETON;
            p.skin = p.shirt = p.hair = unchecked((int)0xFFe9e5d3U); p.pants = unchecked((int)0xFFe3dfccU);
            p.charT = 0f; p.burning = false;
            recolor(p);
            for (int i = 0; i < Person.NPARTS; i++) p.bleed[i] = 0f;
            for (int i = Person.UARM_F; i < Person.NPARTS; i++) {
                if (i == Person.FOOT_F || i == Person.FOOT_B) continue;
                foreach (Shape s in p.rb[i].shapes) s.r *= 0.6f;
            }
            fx.smoke(p.cx(), p.cy(), 16f, unchecked((int)0xFF8fd14aU));
        }

        // ------------------------------------------------------------------------------ grabbing -----

        public RB[] grabbed = new RB[8];
        public int grabCount;

        // ---------------------------------------------------------------------------- construction ----

        public int detonateC4() {
            int n = 0;
            for (int i = 0; i < ents.size(); i++) {
                Ent e = ents.get(i);
                if (e is Prop && ((Prop) e).type == Items.C4 && ((Prop) e).fuse < 0f) { ((Prop) e).fuse = 0.05f + n * 0.08f; n++; }
            }
            return n;
        }

        /** A rope: a chain of capsules between two anchor points, pinned to the bodies at both ends. */
        public Ent rope(RB a, float ax, float ay, RB b, float bx, float by) {
            float dx = bx - ax, dy = by - ay, len = (float) Math.sqrt(dx * dx + dy * dy);
            int n = Math.max(2, Math.min(70, (int) (len / 16f)));
            if (sim.bodies.size() + n > MAX_BODIES) return null;
            Prop r = ropeShell(n, ax, ay, bx, by);
            RB prev = a;
            float px = ax, py = ay;
            for (int i = 0; i < n; i++) {
                RB seg = r.bodies.get(i);
                Joint sj = Joint.pin(prev, seg, px, py);
                sj.breakForce = 9e7f;
                r.joint(sj);
                sim.add(sj);
                px = ax + dx * (i + 1) / n; py = ay + dy * (i + 1) / n;
                prev = seg;
            }
            Joint j = Joint.pin(prev, b, bx, by);
            j.breakForce = 9e7f;
            r.joint(j);
            sim.add(j);
            stats.links++;
            return r;
        }

        /** The bodies of a rope without any joint (also used when loading a scene). */
        public Prop ropeShell(int n, float ax, float ay, float bx, float by) {
            float dx = bx - ax, dy = by - ay, len = (float) Math.sqrt(dx * dx + dy * dy);
            float ang = (float) Math.atan2(dy, dx), seg = len / n;
            Prop r = Prop.of(Items.ROPE_ITEM);
            r.param = n;
            int g = ++Person.groupSeq;
            for (int i = 0; i < n; i++) {
                float t = (i + 0.5f) / n;
                RB s = new RB(ax + dx * t, ay + dy * t, ang);
                s.add(Shape.capsule(Math.max(2f, seg / 2f - 1.5f), 3.2f).mat(0.6f, 0.5f, 0.02f).grp(g));
                s.linDamp = 0.1f; s.angDamp = 0.3f;
                r.body(s);
                sim.add(s);
            }
            ents.add(r);
            return r;
        }

        /** Welds or pins two bodies together (the pivot is the first anchor, or a wheel's own centre). */
        public Joint link(RB a, float ax, float ay, RB b, float bx, float by, bool weld) {
            float px = ax, py = ay;
            if (isRound(b) && !isRound(a)) { px = bx; py = by; }
            Joint j = weld ? Joint.weld(a, b, px, py) : Joint.pin(a, b, px, py);
            j.collide = false;
            if (weld) j.breakForce = 2.5e8f;
            sim.add(j);
            stats.links++;
            if (!weld) {
                Prop wa = a.user is Prop ? (Prop) a.user : null, wb = b.user is Prop ? (Prop) b.user : null;
                Prop wheel = wb != null && wb.motorized ? wb : (wa != null && wa.motorized ? wa : null);
                if (wheel != null) { if (wheel.motor == 0) wheel.motor = 1; setMotor(wheel); }
            }
            return j;
        }

        private static bool isRound(RB b) {
            return b.shapes.size() == 1 && b.shapes.get(0).type == Shape.CIRCLE;
        }

        /** Applies a wheel's motor state to every pin it has. */
        public void setMotor(Prop wheel) {
            RB w = wheel.main();
            for (int i = 0; i < w.joints.size(); i++) {
                Joint j = w.joints.get(i);
                if (j.kind != Joint.REVOLUTE || j.user != null) continue;
                j.motor = wheel.motor != 0;
                j.motorSpeed = wheel.motor * 9.5f * (j.b == w ? 1f : -1f);
                j.motorMax = 6e7f;
            }
        }

        /** Places a ready-made construction. Returns its pieces (for undo). */
        public JList<Ent> buildAt(int item, float x, float y) {
            float fl = sim.floorY;
            x = Math.max(sim.wallL + 150, Math.min(sim.wallR - 150, x));
            JList<Ent> list = Build.build(this, item, x, fl);
            if (!list.isEmpty()) fx.add(Fx.GLOW, x, fl - 60, 0, 0, 0.25f, 120f, unchecked((int)0xFFffffffU));
            return list;
        }

        /** Loading: a person of the given item, without the spawn effects or position clamping. */
        public Person newPersonRaw(int item, float scale, int dir, int kind) {
            if (!canAdd()) return null;
            Person.headScale = 1f;
            Person p = Person.create(sim, 400f, -100f, scale, dir, kind, rnd);
            p.item = item;
            ents.add(p);
            return p;
        }

        /** Loading: a prop of the given item at the origin of the room. */
        public Ent spawnRaw(int item) {
            Ent e;
            if (item == Items.TURRET) e = add(Prop.turret(sim, 400f, -100f, 1));
            else if (item == Items.DRONE) e = add(Prop.drone(sim, 400f, -200f));
            else {
                Prop q = Prop.make(sim, item, 400f, -100f, rnd);
                if (q == null) return null;
                q.register(sim);
                e = add(q);
            }
            return e;
        }

        /** Loading: cut a joint without effects. */
        public void silentSever(Person p, int j) {
            if (p.severed[j]) return;
            if (!p.jt[j].removed) sim.remove(p.jt[j]);
            p.severed[j] = true;
            int g = ++Person.groupSeq;
            foreach (int part in DETACH[j]) foreach (Shape s in p.rb[part].shapes) s.group = g;
        }
    }
